// Turns the AC on when there's enough surplus going to the grid, off when we start importing.
// Once the AC is running its own draw comes out of the export, so the two thresholds must be
// far enough apart (ON_EXPORT should be more than the AC's draw) or it will flip on and off.
const ON_EXPORT = 2.5;   // kW exported before turning the AC on
const OFF_IMPORT = 0.3;  // kW imported before turning the AC off
const ON_POLLS = 2;      // polls in a row above ON_EXPORT before switching on
const OFF_POLLS = 2;     // polls in a row above OFF_IMPORT before switching off
const MIN_SOC = 0;       // optionally require the battery to be at least this full (%)

const grid = msg.payload.gridPower;
if (typeof grid !== "number") {
    return null;
}

let state = context.get("state") || "off";
let count = context.get("count") || 0;
const soc = msg.payload.SoC;
const socOk = typeof soc !== "number" || soc >= MIN_SOC;

if (state === "off") {
    count = (grid >= ON_EXPORT && socOk) ? count + 1 : 0;
    if (count >= ON_POLLS) {
        state = "on";
        count = 0;
    }
} else {
    count = (grid <= -OFF_IMPORT || !socOk) ? count + 1 : 0;
    if (count >= OFF_POLLS) {
        state = "off";
        count = 0;
    }
}

const changed = state !== context.get("state");
context.set("state", state);
context.set("count", count);
node.status({ fill: state === "on" ? "green" : "grey", shape: "dot", text: `AC ${state}, grid ${grid} kW` });

// Only send when the state changes
return changed ? { topic: "ac", payload: state } : null;
